import { useId } from "react";

/**
 * Brand marks, inlined as plain SVG instead of pulled from an icon package.
 * Every mark here is the real brand artwork — the multicolour wordmarks and
 * glyphs are the point of a stack chip, and a monochrome stand-in loses them.
 *
 * Marks published as white-on-transparent (PHP, MySQL, Codex) are re-filled
 * with `currentColor`; on the light theme's white surface they would otherwise
 * disappear. Marks needing `id` references (Next.js, Node, Supabase) derive
 * them from `useId` so repeated instances never collide in the DOM.
 */

/** `useId` returns colons, which are legal but awkward in `url(#…)`. */
function useDomId() {
  return useId().replace(/:/g, "");
}

